anti_pattern:
// Serial ripple min-finder: 3 sequential comparator stages
assign m1 = (a < b) ? a : b;
assign m2 = (m1 < c) ? m1 : c;
assign min_o = (m2 < d) ? m2 : d;

golden_template:
// Balanced binary tree min-finder: 2 parallel comparator stages (reduces ltp -noff depth)
assign min_ab = (a < b) ? a : b;
assign min_cd = (c < d) ? c : d;
assign min_o  = (min_ab < min_cd) ? min_ab : min_cd;

canary_spec.bad_canary_sv:
module canary_test(input logic [7:0] a, b, c, d, output logic [3:0] min_o);
  assign min_o = (a < b) ? (b + 16'd999) : (c + d);
endmodule

canary_spec.good_canary_sv:
module canary_test(input logic [7:0] a, b, c, d, output logic [7:0] min_o);
  wire [7:0] min_ab = (a < b) ? a : b;
  wire [7:0] min_cd = (c < d) ? c : d;
  assign min_o = (min_ab < min_cd) ? min_ab : min_cd;
endmodule

golden_template:
// [GOLDEN PATTERN] Single shared adder with pre-multiplexed operand
wire [W-1:0] selected_offset = sel_i ? offset_a_i : offset_b_i;
assign res_o = base_i + selected_offset;

canary_spec.bad_canary_sv:
module canary_test(input logic sel_i, input logic [7:0] base_i, off_a, output logic [7:0] res_o);
  always_comb begin if (sel_i) res_o = base_i + off_a; end
endmodule

canary_spec.good_canary_sv:
module canary_test(input logic sel_i, input logic [7:0] base_i, off_a, off_b, output logic [7:0] res_o);
  wire [7:0] off_mux = sel_i ? off_a : off_b;
  assign res_o = base_i + off_mux;
endmodule

golden_template:
// [GOLDEN PATTERN] Parameterized exact bit-width ($clog2(N))
localparam int IDX_W = $clog2(N_BITS);
logic [IDX_W-1:0] bit_idx_q;

canary_spec.bad_canary_sv:
module canary_test(input logic clk_i, output logic [2:0] idx_o);
  int cnt_q;
  always_ff @(posedge clk_i) cnt_q <= cnt_q + 1;
  assign idx_o = cnt_q;
endmodule

canary_spec.good_canary_sv:
module canary_test(input logic clk_i, rst_ni, output logic [2:0] idx_o);
  logic [2:0] cnt_q;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) cnt_q <= 3'd0;
    else         cnt_q <= cnt_q + 3'd1;
  end
  assign idx_o = cnt_q;
endmodule

golden_template:
// [GOLDEN PATTERN] Operand Isolation: force datapath inputs to 0 when unit is inactive
wire [7:0] iso_a = valid_i ? data_a_i : 8'd0;
wire [7:0] iso_b = valid_i ? data_b_i : 8'd0;
assign sum_o = iso_a + iso_b;

canary_spec.bad_canary_sv:
module canary_test(input logic clk_i, valid_i, input logic [7:0] a_i, b_i, output logic [7:0] sum_o);
  always_ff @(posedge clk_i) sum_o = a_i + b_i + {7'd0, valid_i};
endmodule

canary_spec.good_canary_sv:
module canary_test(input logic valid_i, input logic [7:0] a_i, b_i, output logic [7:0] sum_o);
  wire [7:0] iso_a = valid_i ? a_i : 8'd0;
  wire [7:0] iso_b = valid_i ? b_i : 8'd0;
  assign sum_o = iso_a + iso_b;
endmodule
